(23, 'דפים אחרים', 'שאלון (מייק-קיט) ראשי', 0, 'באנר שאלון (מייק-קיט)', '', '', '', '', 'שאלונים', '', '', '2025-08-04 23:55:29', 0),
(24, 'דפים אחרים', 'תשלום ראשי', 0, 'באנר תשלום', '', '', '', '', 'תשלום', '', '', '2025-07-31 15:13:40', 0),
(25, 'דפים אחרים', 'שאלון (מדליאן) ראשי', 0, 'באנר שאלון (מדליאן)', '', '', '', '', 'שאלונים', '', '', '2025-08-04 23:55:29', 0),
(26, 'דפים אחרים', 'איפוס סיסמה ראשי', 0, 'באנר איפוס סיסמה', '', '', '', '', 'החשבון שלי', '', '', '2025-08-04 23:55:29', 0),
(27, 'דפים אחרים', 'הצהרת נגישות ראשי', 0, 'באנר הצהרת נגישות', '', 'הצהרת נגישות – makekit', '', '', 'הצהרת נגישות', '', '<h2>מבוא</h2><p>חברת תקדים בחינוך – מקדמת ופועלת להנגשת מכלול שירותיה ומתקניה בהתאם לחוק שוויון לאנשים עם מוגבלויות ותקנות הנגישות השונות. אנו רואים בלקוחות עם מוגבלות שווי זכויות, הזכאים ליהנות מנגישות מלאה בכל שירותי המשרד, בביקור במשרד ובאתר האינטרנט.</p><p>האינטרנט מהווה כיום את המאגר הגדול ביותר לחופש המידע עבור כל המשתמשים בכלל ולמשתמשים עם מוגבלויות בפרט. ככזה, אנו שמים חשיבות רבה במתן אפשרות שווה לאנשים עם מוגבלויות לשימוש במידע המוצג באתר ולאפשר חווית גלישה טובה יותר. אנו שואפים להבטיח כי השירותים יהיו נגישים לאנשים עם מוגבלויות ועל כן, אנו משקיעים משאבים רבים להקל את השימוש באתר ובשירותי המשרד עבור אנשים עם מוגבלויות ככל האפשר, מתוך אמונה כי לכל אדם מגיעה הזכות להיות בשוויון, כבוד, נוחות ועצמאות.</p><h2>נגישות אתר אינטרנט</h2><p>אתר אינטרנט נגיש הוא אתר המאפשר לכל אדם עם כל סוג של מוגבלות לגלוש באותה רמה של יעילות והנאה ככל הגולשים. כ- 20 עד 25 אחוזים מהאוכלוסייה נתקלים בקשיי שימוש באינטרנט ועשויים להיטיב מתכני אינטרנט נגישים יותר, כך על פי מחקר שנערך בשנת 2003 ע\"י חברת מייקרוסופט.</p><p>באתר זה בוצעו התאמות ושיפורים בהתאם להמלצות הנגישות וכמו כן, האתר מותאם לתצוגה בדפדפנים הנפוצים ולשימוש בטלפון הסלולרי.<br>מטרתנו הינה לשפר את אתר האינטרנט כך שיהיה זמין, נוח וידידותי לשימוש עבור אנשים עם מוגבלויות על סוגיהם השונים המתקשים בהפעלת המחשב והאינטרנט ובכך לאפשר לגלוש בנוחות ובמהירות וליהנות מהתכנים ומהשירותים שפותחו עבור הלקוחות הגולשים. יצוין, כי למרות מאמצנו להנגיש את כלל הדפים באתר, יתכן כי יתגלו חלקים באתר (דפים, פונקציות מסיומות וכיו\"ב) שאינם נגישים. מלאכת ההנגשה הינה תהליך מתמשך ומתפתח, ואנו שואפים לשפר את נגישות האתר לכל לקוחותינו, כולל לקוחותינו עם מוגבלויות.</p><h2>תכונות הנגישות הנתמכות</h2><ul><li>אתר זה מופעל באמצעות כלי עזר/תוסף הנגשה One Click Accessibility – סרגל נגישות בקליק.</li><li>הגדלת טקסט.</li><li>הקטנת טקסט.</li><li>גווני אפור.</li><li>ניגודיות גבוהה.</li><li>ניגודיות הפוכה.</li><li>רקע בהיר.</li><li>הדגשת קישורים.</li><li>פונט קריא</li><li>ניווט מתקדם באמצעות מקלדת.</li><li>ניווט מקלדת –  אינו פעיל בגלישה באמצעות טלפון סלולרי או טאבלט.</li></ul><p> </p><p><strong>איך עובד ניווט מקלדת?</strong></p><ul><li>באתר ישנו אייקון לחיץ הפותח את תפריט כלי עזר/תוסף ההנגשה.</li><li>לחיצה על מקש  TAB תתחיל ניווט באמצעות המקלדת.</li><li>למעבר בין אלמנטים בדף יש להקיש על מקש TAB </li><li>למעבר אחורה יש להקיש על המקשים SHIFT + TAB</li></ul><h2>נגישות מלאה</h2><p>אנו בחברת תקדים בחינוך – עושים את מיטב מאמצינו להנגשת האתר במלואה ולאפשר לכלל האוכלוסייה ליהנות מתכניו, יחד עם זאת ייתכן כי דפים מסוימים עדיין לא הונגשו בצורה מלאה.</p><h2>הצהרת הנגישות תקפה נכון לתאריך:</h2><p>15.12.2022, 10:00</p>', '2025-08-04 23:55:29', 0);

