(57, 'pages', 'page_id', 8, '6bae1becf4fa692af52ada666131487e', 'png', 'Wholesale Content', 'יופי', '', '', 1, 1, 1),
(58, 'pages', 'page_id', 10, '98230a1548038a7b5a0f056f215b5b64', 'jpg', 'Drawing Content', '', '', '', 3, 0, 1),
