(62, 'pages', 'page_id', 10, 'f2407306739799fc0ff66a5987e2cf9c', 'jpg', 'Drawing Content', '', '', '', 3, 4, 1),
(120, 'question_answers', 'qa_id', 60, '2f3c77267aa4a3a1f33e3781d6c07286.png', 'jpg', 'answer_image', NULL, NULL, NULL, 0, 1, 1),
(122, 'pages', 'page_id', 6, '6f1d773fdb33d82300a1b22916d17145', 'jpg', 'תוכן חוגים', 'אלקטרוניכיף', '', 'חוג זה המתקיים ללא מלחם, לבטיחות מירבית, פותח והותאם במיוחד לגילאים צעירים.\r\nאת החוג ילוו בורי המברג ואלי האלקטרון בסיפורים המשלבים בין עולם הדמיון של הילדים, בין ערכים חינוכיים ובין תחום האלקטרוניקה.\r\nבמסגרת החוג, התלמידים ילמדו חוקים בסיסיים בחשמל, יקראו שרטוטים, יחשבו ערכים של רכיבים, יכירו מושגים שונים ויבנו פרויקטים מגניבים.\r\nהתלמידים יבצעו ניסויים על הפרויקטים ובסיום כל פרויקט יקחו אותו לבית.', 1, 1, 1),
(123, 'pages', 'page_id', 6, '08a785d02e1c79f5f77ba2a88b1ad5b5', 'jpg', 'תוכן חוגים', 'רובוטרוניק', '', 'חוג זה המתקיים ללא מלחם, לבטיחות מירבית, פותח והותאם במיוחד לגילאים צעירים.\r\nאת החוג ילוו בורי המברג ואלי האלקטרון בסיפורים המשלבים בין עולם הדמיון של הילדים, בין ערכים חינוכיים ובין תחום האלקטרוניקה.\r\nבמסגרת החוג, התלמידים ילמדו חוקים בסיסיים בחשמל, יקראו שרטוטים, יחשבו ערכים של רכיבים, יכירו מושגים שונים ויבנו פרויקטים מגניבים.\r\nהתלמידים יבצעו ניסויים על הפרויקטים ובסיום כל פרויקט יקחו אותו לבית.', 1, 1, 1),
(124, 'pages', 'page_id', 6, 'ea8746d394d408ee2e230d6500622f54', 'jpg', 'תוכן חוגים', 'למה-דע', '', 'בחוג זה לומדים על מדענים ותגליות גדולות, באמצעות בניית מוצרים המבוססים על תגליות אלו.\r\nבין המדענים שנלמד:\r\nברנולי, טסלה, ניוטון, לנס, הוקינג, איינשטיין, ארכימדס, גלילאו ועוד…\r\nתחומים בהם נעסוק:\r\nאנרגיה, המרת אנרגיה, חשמל, מכניקה, אופטיקה, כימיה, טכנולוגיה ועוד…\r\nבמהלך החוג התלמידים יבנו מעל 20 מוצרים שונים.', 1, 1, 1),
(125, 'pages', 'page_id', 6, '004a415ee7c500ca5174ba764cf91164', 'jpg', 'תוכן חוגים', 'קיד-מה', '', 'חוג מדעים מתקדם בעקבות ממציאים מפורסמים ופיתוחים גדולים, באמצעות בניית מוצרים המבוססים על פיתוחים אלו.\r\nבין הממציאים שנלמד:\r\nאהרון אהרונסון, מארי קירי, חיים וייצמן, פריץ-בר, יעקב מוטס, דב מורן, בני לנדא, צבי תבור, שי אגסי ועוד…\r\nתחומים בהם נעסוק:\r\nהמרת אנרגיה, אנרגיה ירוקה, חשמל, תעשיה, חקלאות, כימיה ועוד…\r\nבמהלך החוג התלמידים יבנו מעל 15 מוצרים שונים.', 1, 1, 1),
(126, 'pages', 'page_id', 6, '63d64034b6a9000fa6f2ea5f28df4469', 'jpg', 'תוכן חוגים', '!Scottie Go', '', 'משחק חדשני ללימוד שפת תכנות לילדים ולצעירים. רמות קושי שונות וגיבורים ידידותיים במשחק מאפשרים לימוד תכנות מגיל צעיר, ללא צורך בניסיון קודם, כמו גם אספקת סביבות תכנות מאתגרות לשחקנים מנוסים יותר.\r\n!Scottie Go סדרת המשחקים כוללת חייזר ידידותי בשם סקוטי, שחווה הרפתקאות רבות בזמן שהוא מטייל בחלל עם החללית שלו.\r\nעל ידי עזרה לסקוטי, שחקנים צוברים ידע בתכנות ומפתחים מיומנויות וכישורים חשובים.', 1, 1, 1),
(127, 'pages', 'page_id', 6, '6a198652d3dd765c4c7aa8b5dbc2fac5', 'jpg', 'תוכן חוגים', 'כוח המוח', '', 'אנו מאמינים שהדרך הטובה ביותר לרכוש הכנה לחיים היא דרך משחק.\r\nתחומים הנלמדים בבתי ספר אך מיושמים בדרכים שונות במהלך החיים.\r\nלשם כך פיתחנו תכנית המשלבת משחקים, חוויה ותובנות הנדרשות להמשך החיים.\r\nבמהלך המשחק נלמד את התחומים הבאים:\r\nאסטרטגיה, ניהול זמן, מתמטייקה, קיימות, מעגלי חיים ותכנות.', 1, 1, 1),
(128, 'pages', 'page_id', 6, '9b89f04f503ec21c1e1e9987ed3ae607', 'jpg', 'תוכן חוגים', 'צ\'יילדווד', '', 'חוג מקצועי זה משלב נגרות, צריבה בעץ, ארכיטקטורה והמון המון כיף.\r\nהתלמידים ישתמשו בכלי עבודה מגוונים דוגמת:\r\nקאטר, פלייר, מלחציים, פטיש, שופין, משקפי מגן, מלחם ועוד…', 1, 1, 1);

