CREATE TABLE `products` (
  `pro_id` int(11) NOT NULL,
  `pro_code` varchar(25) DEFAULT NULL,
  `user_id` int(11) NOT NULL,
  `cate_id` int(11) NOT NULL,
  `brand_id` int(11) NOT NULL,
  `name` varchar(255) NOT NULL,
  `description` text DEFAULT NULL,
  `short_description` text DEFAULT NULL,
  `ingredients` text DEFAULT NULL,
  `how_to_use` text DEFAULT NULL,
  `price` decimal(8,2) NOT NULL,
  `price_poi` decimal(8,2) DEFAULT 0.00,
  `quantity` int(11) NOT NULL DEFAULT 0,
  `weight` int(2) NOT NULL DEFAULT 1,
  `barcode` varchar(50) DEFAULT NULL,
  `slug_url` text NOT NULL,
  `seo_title` varchar(255) DEFAULT NULL,
  `seo_url` varchar(255) DEFAULT NULL,
  `seo_keyword` varchar(255) DEFAULT NULL,
  `seo_description` varchar(255) DEFAULT NULL,
  `view_count` int(11) NOT NULL DEFAULT 0,
  `sales_count` int(11) NOT NULL DEFAULT 0,
  `added_date` datetime NOT NULL DEFAULT current_timestamp(),
  `status` int(1) NOT NULL DEFAULT 0 COMMENT '0=available | 1=not available | 2=seller off',
  `credit_type_id` int(11) DEFAULT 1 COMMENT 'refer from credit_type table',
  `minimum_eligiblity_value` int(11) DEFAULT NULL COMMENT 'When the credit_type is Medalian Currency or Makekit currency then the eligible points value will be added to this field.'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

