INSERT INTO `products` (`pro_id`, `pro_code`, `user_id`, `cate_id`, `brand_id`, `name`, `description`, `short_description`, `ingredients`, `how_to_use`, `price`, `price_poi`, `quantity`, `weight`, `barcode`, `slug_url`, `seo_title`, `seo_url`, `seo_keyword`, `seo_description`, `view_count`, `sales_count`, `added_date`, `status`, `credit_type_id`, `minimum_eligiblity_value`) VALUES
(1, NULL, 1, 4, 3, 'אזעקוד', 'ילדך רוצה פרטיות? קיט האזעקוד יאפשר לילדך לשמור על פרטיותו על ידי אזעקה שמופעלת בעזרת קוד.\nהאזעקה מתריעה בעוצמה במקרים בהם הדלת או החלון נפתחים ללא אישור.\nכאשר הדלת נסגרת, ההתרעה אינה נעצרת, אלא ממשיכה עד לביטול.\nמספר רכיבים:\nרמת קושי: מקצוענים – 10', NULL, NULL, NULL, '80.00', '80.00', 100, 1, NULL, 'אזעקוד', NULL, NULL, NULL, NULL, 0, 0, '2025-09-11 17:23:11', 0, 1, NULL),
(2, NULL, 1, 4, 3, 'אזעכיס', 'הילד רוצה פרטיות מאחיו? האזעקה תרחיק גם את האח העקשן ביותר.\nאזעקה קטנה, רב שימושית ופשוטה לתפעול.\nהאזעקה מתחברת לכל דלת וחלון.\nהחיבור מתבצע על ידי דבק דו צדדי והינו ידידותי גם לבית מושכר.\nהאזעקה מתריעה בעוצמה במקרים בהם הדלת או החלון נפתחים ללא אישור.\nכאשר הדלת נסגרת, ההתרעה אינה נעצרת, אלא ממשיכה עד לכיבוי באופן ידני.\nמספר רכיבים: 11\nרמת קושי: מתחילים – 3\nהרכבת אזעכיס', NULL, NULL, NULL, '32.60', '32.60', 100, 1, NULL, 'אזעכיס', NULL, NULL, NULL, NULL, 0, 0, '2025-09-11 17:23:11', 0, 1, NULL),
(3, NULL, 1, 4, 3, 'אתרוג מאיר (3 לדים)', 'הקישוט הייחודי לסוכה שכולם יעופו עליו והילד יוכל להראות את היכולות שלו ולא רק בציור.\nאתרוג מבוסס לדים.\nהאתרוג מאיר בצבעים מתחלפים.\nניתן לתלות אותו כקישוט בסוכה.\nמספר רכיבים: 9\nרמת קושי: מתחילים – 2', NULL, NULL, NULL, '21.80', '21.80', 88, 1, NULL, 'אתרוג-מאיר-3-לדים', NULL, NULL, NULL, NULL, 0, 0, '2025-09-11 17:23:11', 0, 1, NULL),
(4, NULL, 1, 4, 3, 'גלווובוס', 'רוצה לעודד את הילד לחסוך? רוצה לעודד אותו לתת צדקה? קופת הגלובוס הייחודית שלנו מעודדת את הילדים להכניס מטבעות אל הקופה.\nבכל פעם שמטבע נכנס נדלקים אורות מהבהבים.\nבנוסף ניתן לצבוע את הגלובוס וללמוד באמצעותו את היבשות השונות.\nגלובוס ייחודי המשמש כקופת חסכון.\n15 רכיבים\nרמת קושי: מתחילים – 3\nהסבר גלווובוס | הרכבת גלובוס', NULL, NULL, NULL, '38.10', '38.10', 100, 1, NULL, 'גלווובוס', NULL, NULL, NULL, NULL, 0, 0, '2025-09-11 17:23:11', 0, 1, NULL),
(5, NULL, 1, 4, 3, 'וינקר לאופניים', 'רוצה להיות רגוע יותר כשהילד נוסע על האופניים או על הקורקינט? הויינקר שהילד בונה יעודד אותו להשתמש בו ולהתגאות בו ואתה תוכל להיות רגוע יותר בידיעה שהילד יותר צפוי לנהגים.\nוינקר איכותי לאופניים או לקורקינט הפועל על ידי שלט חוטי קטן, שגם אותו מרכיבים.\nהוינקר מתחבר בקלות לכידון של האופניים או של הקורקינט.\nתאורת לדים קבועה אדומה.\nתאורת לדים צהובה מהבהבת שמתפקדת כמערכת איתות ימינה ושמאלה.\nמספר רכיבים: 30 וינקר, 6 שלט\nרמת קושי: מתקדמים – 9\nהרכבת וינקר', NULL, NULL, NULL, '54.40', '54.40', 100, 1, NULL, 'וינקר-לאופניים', NULL, NULL, NULL, NULL, 0, 0, '2025-09-11 17:23:11', 0, 1, NULL),
(6, NULL, 1, 4, 3, 'מדליכוס', 'הכוס הכי מגניבה ויחודית – כזו שהילד ירצה לשתות רק איתה, ולך יהיה נוח לנקות.\nכוס בטיחות המודדת את טמפרטורת מים.\nבמידה והמים חמים הכוס תתריע בכך שאור ידלק.\nהכוס מיוצרת מפלסטיק מאושר למזון והיא בטוחה לשתייה.\nניתן להסיר את החלקים האלקטרונים בקלות ולשטוף את הכוס בין שימוש לשימוש.\nמספר רכיבים: 8\nרמת קושי: מתחילים – 2\nהסבר מדליכוס | הרכבת מדליכוס', NULL, NULL, NULL, '38.10', '38.10', 100, 1, NULL, 'מדליכוס', NULL, NULL, NULL, NULL, 0, 0, '2025-09-11 17:23:11', 0, 1, NULL),
(7, NULL, 1, 4, 3, 'מאוורר שולחני (מטוס)', 'המאוורר הכי שווה – גם עשה זאת בעצמך, גם לומדים אלקטרוניקה, גם עושה אורות ונעים וגם נראה מגניב וכולם ישאלו אותך עליו.\nקיט מאוורר מדליק בצורת מטוס שעושה אור ואוויר כאשר מדליקים אותו.\nניתן לשים אותו כקישוט פרקטי ומגניב על שולחן הלמידה.\nמספר רכיבים: 14\nרמת קושי: בינוני – 5', NULL, NULL, NULL, '48.90', '48.90', 100, 1, NULL, 'מאוורר-שולחני-מטוס', NULL, NULL, NULL, NULL, 0, 0, '2025-09-11 17:23:11', 0, 1, NULL),
(8, NULL, 1, 4, 3, 'פעמון לבית', 'כל אחד רוצה פעמון מגניב לבית. לקיט הפעמון שלנו יש שלוש עשרה מנגינות ישראליות שניתן לבחור מביניהן את המנגינה האהובה.\nבנוסף, ניתן לקבע את המגינה המועדפת עליכם.\nבכל פעם שלוחצים על הפעמון תתנגן המנגינה שנבחרה.\nמספר רכיבים:\nרמת קושי: מקצוענים – 10', NULL, NULL, NULL, '76.10', '76.10', 100, 1, NULL, 'פעמון-לבית', NULL, NULL, NULL, NULL, 0, 0, '2025-09-11 17:23:11', 0, 1, NULL),
(9, NULL, 1, 4, 3, 'צ\'קלקה', NULL, NULL, NULL, NULL, '87.00', '87.00', 100, 1, NULL, 'צקלקה', NULL, NULL, NULL, NULL, 0, 0, '2025-09-11 17:23:11', 0, 1, NULL),
(10, NULL, 1, 6, 3, 'רכב אויר', 'רכב האויר הכי מגניב בעיר, גם הילד בונה אותו בעצמו וגם הוא יוכל לשחק איתו שעות אחרי.\nרכב מקורי ומהנה.\nהרכב נוסע בכל פעם שמקרבים אליו יד או חפץ.\nמספר רכיבים: 36\nרמת קושי: מקצוענים – 10', NULL, NULL, NULL, '76.10', '76.10', 100, 1, NULL, 'רכב-אויר', NULL, NULL, NULL, NULL, 0, 0, '2025-09-11 17:23:11', 0, 1, NULL),
(11, NULL, 1, 4, 3, 'רכב פס', 'רכב הפס הכי מגניב בעיר, גם הילד בונה אותו בעצמו וגם הוא יוכל לשחק איתו שעות אחרי ולהוסיף לו מסלולים משלו.\nרכב מקורי ומהנה שמגיע יחד עם מסלול מעגלי מודפס.\nהרכב מתוכנן כך שהוא נוסע ועוקב אחרי פס שחור.\n(מסלול מעגלי מצורף לערכה).\nמספר רכב: 44\nרמת קושי: מקצוענים – 10\nהרכבת רכב 1 | הרכבת רכב 2 | הרכבת רכב 3 | הרכבת רכב 4 | הרכבת רכב 5 | הרכבת רכב 6-7 | הרכבת רכב 8 | הרכבת רכב 9', NULL, NULL, NULL, '130.50', '130.50', 100, 1, NULL, 'רכב-פס', NULL, NULL, NULL, NULL, 0, 0, '2025-09-11 17:23:11', 0, 1, NULL),
(12, NULL, 1, 4, 3, 'רעשן גדול', 'רעשן גדול מבוסס לדים וזמזם אלקטרוני.\nרעשן זה מיוחד במינו, הילדים מרכיבים אותו ואת האלקטרוניקה שמתחברת אליו.\nבנוסף לרעש הרגיל שרעשן עושה, מצרפים אליו גם זמזם, שהופך את הרעשן למרעיש אף יותר לשמחת כולם.\nהמוצר מאיר בצבעים מתחלפים.\nמספר רכיבים: 17\nרמת קושי: מתחילים – 3\nהרכבת רעשן 1 | הרכבת רעשן 2 | הרכבת רעשן 3', NULL, NULL, NULL, '27.20', '27.20', 100, 1, NULL, 'רעשן-גדול', NULL, NULL, NULL, NULL, 0, 0, '2025-09-11 17:23:11', 0, 1, NULL),
(13, NULL, 1, 4, 3, 'רעשן קטן', 'רעשן מיני מבוסס לדים וזמזם אלקטרוני.\nרעשן זה מיוחד במינו, הילדים מרכיבים אותו ואת האלקטרוניקה שמתחברת אליו.\nבנוסף לרעש הרגיל שרעשן עושה, מצרפים אליו גם זמזם, שהופך את הרעשן למרעיש אף יותר לשמחת כולם.\nהמוצר מאיר בצבעים מתחלפים.\nמספר רכיבים: 11\nרמת קושי: מתחילים – 1\nהרכבת רעשן 1 | הרכבת רעשן 2', NULL, NULL, NULL, '19.60', '19.60', 100, 1, NULL, 'רעשן-קטן', NULL, NULL, NULL, NULL, 0, 0, '2025-09-11 17:23:11', 0, 1, NULL),
(14, NULL, 1, 4, 3, 'שקדיה', 'רוצה לשדרג את עריכת השולחן? השקדיה מוסיפה אור, צבע וייחודיות לכל שולחן פשוט ולכל יום הולדת. בנוסף אין כמו לראות את הילד שלך מתגאה במשהו מגניב שהוא עשה.\nעץ יפה ושימושי המשמש לתליית אביזרים קטנים.\nניתן להשתמש בו בטו\' בשבט ובימי הולדת,\nככלי הגשה של ממתקים ופירות יבשים.\nעוד ניתן לתלות עליו עגילים, טבעות, מתנות קטנות, וכד\'.\nבחדר מואר נדלקים ארבעה לדים, כשהתאורה נכבת נדלקים עוד ארבעה.\nמספר רכיבים: 24\nרמת קושי: בינוני – 4\nהרכבת שקדיה 1 | הרכבת שקדיה 2 | הרכבת שקדיה 3 | הרכבת שקדיה 4', NULL, NULL, NULL, '65.20', '65.20', 100, 1, NULL, 'שקדיה', NULL, NULL, NULL, NULL, 0, 0, '2025-09-11 17:23:11', 0, 1, NULL),
(15, NULL, 1, 4, 3, 'תאורת לילה (7 לדים)', 'מי מפחד מהחושך? תאורה יחודית שתעודד את הילד בלילה שלא לפחד.\nברגע שהאור נכבה התאורה נדלקת בשלל צבעים עדינים שמפחיתים מעט מהחושך.\nתאורת חירום איכותית ומדליקה.\nהתאורה מורכבת מ – 7 לדים צבעוניים שידלקו\nבכל פעם שהאור יכבה.\nמספר רכיבים: 22\nרמת קושי: בינוני – 6\nהרכבת תאורת לילה', NULL, NULL, NULL, '43.50', '43.50', 100, 1, NULL, 'תאורת-לילה-7-לדים', NULL, NULL, NULL, NULL, 0, 0, '2025-09-11 17:23:11', 0, 1, NULL),
(16, NULL, 1, 4, 3, 'תאורת לילה (2 לדים)', 'מי מפחד מהחושך? תאורה יחודית שתעודד את הילד בלילה שלא לפחד. ברגע שהאור נכבה התאורה נדלקת בשלל צבעים מרגיעים, שמפחיתים מעט מהחושך.\nתאורת חירום איכותית ומדליקה.\nהתאורה מורכבת מ – 2 לדים צבעוניים שידלקו\nבכל פעם שהאור יכבה.\nרכיבים\nרמת קושי: מתחילים – 3\nהרכבת תאורת לילה', NULL, NULL, NULL, '27.20', '27.20', 100, 1, NULL, 'תאורת-לילה-2-לדים', NULL, NULL, NULL, NULL, 0, 0, '2025-09-11 17:23:11', 0, 1, NULL),
(17, NULL, 1, 3, 3, 'אורון', 'תאורת לדים לארון.\nהתאורה נדלקת באופן אוטומטי כל פעם שדלת הארון נפתחת.\nמצויין כפרוייקט ראשון.\nמתאים לקייטנות, סדנאות, חוגים, בניה עצמית.\nהקיט מופעל באמצעות סוללה 12V (כלולה).\nמספר רכיבים: 19.\nזמן עבודה: 2 – 3 שיעורים (מחושב לפי 45 דקות לשיעור).\nדרגת קושי: קל.\nהצגת אורון | הרכבת אורון', NULL, NULL, NULL, '24.00', '24.00', 100, 1, NULL, 'אורון', NULL, NULL, NULL, NULL, 0, 0, '2025-09-11 17:23:11', 0, 1, NULL),
(18, NULL, 1, 3, 3, 'אזעכיס', 'אזעקה קטנה, רב שימושית ופשוטה לתפעול.\nהאזעקה מתחברת לכל דלת\\חלון.\nהאזעקה מתריעה בעוצמה במקרים בהם הדלת\\חלון נפתח\\ת ללא אישור.\nלתפעול האזעקה יש ללחוץ על הלחצן בצד ולהניח את האזעקה על דלת\\חלון, באופן כזה שהלחצן ישאר באותו מצב.\nמצויין כפרוייקט ראשון.\nמתאים לקייטנות, סדנאות, חוגים, בניה עצמית.\nהקיט מופעל באמצעות סוללה 12V (כלולה).\nמספר רכיבים: 17.\nזמן עבודה: 3 שיעורים (מחושב לפי 45 דקות לשיעור).\nדרגת קושי: קל.\nהרכבת אזעכיס', NULL, NULL, NULL, '24.00', '24.00', 100, 1, NULL, 'אזעכיס-1', NULL, NULL, NULL, NULL, 0, 0, '2025-09-11 17:23:11', 0, 1, NULL),
(19, NULL, 1, 3, 3, 'בייסיקול', 'תאורה לדים איכותית לאופניים.\nהתאורה כוללת חיישן תזוזה.\nהתאורה נדלקת באופן אוטומטי בזמן סיבוב הגלגל עליו היא מותקנת.\nמטרת התאורה, להגדיל את מידת הבטיחות של הרוכב באמצעות הוספת תאורה לאופניים.\nמתאים לקייטנות, סדנאות, חוגים, בניה עצמית.\nהקיט מופעל באמצעות סוללה 12V (כלולה).\nמספר רכיבים: 13.\nזמן עבודה: 3 שיעורים (מחושב לפי 45 דקות לשיעור).\nדרגת קושי: קל.\nהרכבת בייסיקול', NULL, NULL, NULL, '24.00', '24.00', 100, 1, NULL, 'בייסיקול', NULL, NULL, NULL, NULL, 0, 0, '2025-09-11 17:23:11', 0, 1, NULL),
(20, NULL, 1, 3, 3, 'דורי', 'קיט רמזור מגניב לחדר (יש\\אין כניסה).\nהרמזור מאופיין בשני סימנים (איקס\\וי) בצבעים אדום וירוק בהתאמה.\nהקיט מאפשר למשתמש לסמן למבקרים פוטנציאלים האם הוא מעוניין בביקור על ידי שינוי הסימנים.\nמצויין כפרוייקט ראשון.\nמתאים לקייטנות, סדנאות, חוגים, בניה עצמית.\nהקיט מופעל באמצעות סוללה 12V (כלולה).\nמספר רכיבים: 24.\nזמן עבודה: 4 שיעורים (מחושב לפי 45 דקות לשיעור).\nדרגת קושי: קל.\nהצגת דורי | הרכבת דורי', NULL, NULL, NULL, '29.40', '29.40', 100, 1, NULL, 'דורי', NULL, NULL, NULL, NULL, 0, 0, '2025-09-11 17:23:11', 0, 1, NULL),
(21, NULL, 1, 3, 3, 'חנוכיס', 'חנוכיית לדים קטנה, איכותית ומרשימה.\nמצוין כפרויקט ראשון.\nמתאים לקייטנות, סדנאות, חוגים, בניה עצמית.\nהקיט מופעל באמצעות סוללה 12V (כלולה).\nמספר רכיבים: 28.\nזמן עבודה: 5 שיעורים (מחושב לפי 45 דקות לשיעור).\nדרגת קושי: קל.\nהרכבת חנוכיס', NULL, NULL, NULL, '29.40', '29.40', 100, 1, NULL, 'חנוכיס', NULL, NULL, NULL, NULL, 0, 0, '2025-09-11 17:23:11', 0, 1, NULL),
(22, NULL, 1, 3, 3, 'מזכירון', 'מכשיר להקלטת תזכורת.\nמצוין כפרויקט ראשון.\nמתאים לקייטנות, סדנאות, חוגים, בניה עצמית.\nהקיט מופעל באמצעות צמד סוללות 3V 2016 (כלולות)\nמספר רכיבים: 25.\nזמן עבודה: 5 שיעורים (מחושב לפי 45 דקות לשיעור).\nדרגת קושי: קל.\nהצגת מזכירון | הרכבת מזכירון', NULL, NULL, NULL, '33.70', '33.70', 100, 1, NULL, 'מזכירון', NULL, NULL, NULL, NULL, 0, 0, '2025-09-11 17:23:11', 0, 1, NULL),
(23, NULL, 1, 3, 3, 'פנסופר', 'פנס עוצמתי וקומפקטי.\nהפנס משמש כמחזיק מפתחות.\nבעזרת הפנס ניתן לשחרר עגלות סופר.\nתאורת הפנס נעשית בעזרת 3 לדים לבנים חזקים.\nמצויין כפרוייקט ראשון.\nמתאים לקייטנות, סדנאות, חוגים, בניה עצמית.\nהקיט מופעל באמצעות סוללה 3V 2032 (כלולה).\nמספר רכיבים: 10.\nזמן עבודה: 2 שיעורים (מחושב לפי 45 דקות לשיעור).\nדרגת קושי: קל.\nהצגת פנסופר | הרכבת פנסופר', NULL, NULL, NULL, '13.00', '13.00', 100, 1, NULL, 'פנסופר', NULL, NULL, NULL, NULL, 0, 0, '2025-09-11 17:23:11', 0, 1, NULL),
(24, NULL, 1, 3, 3, 'תאורת לילה (קופסא)', 'תאורת חירום מבוססת לדים.\nמצוין כפרויקט ראשון.\nמתאים לקייטנות, סדנאות, חוגים, בניה עצמית.\nהקיט מופעל באמצעות סוללה 3V 2032 (כלולה).\nמספר רכיבים: 15.\nזמן עבודה: 3 שיעורים (מחושב לפי 45 דקות לשיעור).\nדרגת קושי: קל.\nהצגת תאורת לילה | הרכבת תאורת לילה', NULL, NULL, NULL, '27.20', '27.20', 100, 1, NULL, 'תאורת-לילה-קופסא', NULL, NULL, NULL, NULL, 0, 0, '2025-09-11 17:23:11', 0, 1, NULL),
(25, NULL, 1, 3, 3, 'תאורת לילה (מחזיק מפתחות)', 'תאורת לילה עוצמתית וקומפקטית.\nהתאורה משמשת כמחזיק מפתחות.\nנדלקת באופן אוטומטי בזמן כיבוי אורות.\nהתאורה נעשית בעזרת 4 לדים לבנים חזקים.\nמצויין כפרוייקט ראשון.\nמתאים לקייטנות, סדנאות, חוגים, בניה עצמית.\nהקיט מופעל באמצעות סוללה 3V 2032 (כלולה).\nמספר רכיבים: 15.\nזמן עבודה: 2 – 3 שיעורים (מחושב לפי 45 דקות לשיעור).\nדרגת קושי: קל.', NULL, NULL, NULL, '17.40', '17.40', 100, 1, NULL, 'תאורת-לילה-מחזיק-מפתחות', NULL, NULL, NULL, NULL, 0, 0, '2025-09-11 17:23:11', 0, 1, NULL),
(26, NULL, 1, 3, 3, 'אורגניתון', 'אורגנית קטנה ומיוחדת באורך אוקטבה, עם יכולת הקלטה.\nהאורגנית כוללת טונים וחצאי טונים.\nמתאים לקייטנות, סדנאות, חוגים, בניה עצמית.\nהקיט מופעל באמצעות סוללה 9V (כלולה).\nמבוסס רכיב PIC.\nמספר רכיבים: 53.\nזמן עבודה: 8 – 9 שיעורים (מחושב לפי 45 דקות לשיעור).\nדרגת קושי: בינוני – קשה.\nהרכבת אורגנית', NULL, NULL, NULL, '72.80', '72.80', 100, 1, NULL, 'אורגניתון', NULL, NULL, NULL, NULL, 0, 0, '2025-09-11 17:23:11', 0, 1, NULL),
(27, NULL, 1, 3, 3, 'אינטרקום', 'קיט המורכב משתי יחידות עצמאיות.\nבין שתי היחידות ניתן לצפצף ולדבר.\nהיחידות מחוברות באמצעות כבל AUX (אנו מספקים כבל באורך 3 מטר).\nלתפעול האינטרקטום, יש לחבר את הכבל המסופק בערכה, בין שתי היחידות.\nמתאים לקייטנות, סדנאות, חוגים, בניה עצמית.\nהקיט מופעל באמצעות צמד סוללות 9V (כלולות).\nמבוסס רכיבים 386, 555.\nמספר רכיבים: 74.\nזמן עבודה: 10 שיעורים (מחושב לפי 45 דקות לשיעור).\nדרגת קושי: בינוני.', NULL, NULL, NULL, '97.80', '97.80', 100, 1, NULL, 'אינטרקום', NULL, NULL, NULL, NULL, 0, 0, '2025-09-11 17:23:11', 0, 1, NULL),
(28, NULL, 1, 3, 3, 'בלטון', 'פעמון נייד לבית עם מגוון מנגינות.\nניתן לבחור מבין המנגינות באמצעות לחצן.\nהחיבור בין המכשיר למיקרופון נעשה באמצעות כבל (AUX).\nמתאים לקייטנות, סדנאות, חוגים, בניה עצמית.\nהקיט מופעל באמצעות סוללה 9V (כלולה).\nמבוסס רכיב PIC.\nמספר רכיבים: 35.\nזמן עבודה: 6 שיעורים (מחושב לפי 45 דקות לשיעור).\nדרגת קושי: בינוני.\nהצגת בלטון | הרכבת בלטון', NULL, NULL, NULL, '76.10', '76.10', 100, 1, NULL, 'בלטון', NULL, NULL, NULL, NULL, 0, 0, '2025-09-11 17:23:11', 0, 1, NULL),
(29, NULL, 1, 3, 3, 'וינקר לאופניים', 'וינקר איכותי לאופניים\\קורקינט.\nתאורת לדים קבועה צהובה.\nתאורת לדים אדומה מתפקדת כמערכת איתות ימינה\\שמאלה.\nהוינקר מתחבר בקלות לכידון של אופניים\\קורקינט.\nהשליטה נעשית על ידי שלט חוטי קטן שאותו יש להרכיב.\nשער כניסה לקיטים מורכבים יותר.\nמתאים לקייטנות, סדנאות, חוגים, בניה עצמית.\nהקיט מופעל באמצעות סוללה 9V (כלולה).\nמבוסס רכיב 555.\nמספר רכיבים: 24.\nזמן עבודה: 5 שיעורים (מחושב לפי 45 דקות לשיעור).\nדרגת קושי: קל – בינוני.\nהרכבת וינקר | הרכבת קופסא', NULL, NULL, NULL, '54.40', '54.40', 100, 1, NULL, 'וינקר-לאופניים-1', NULL, NULL, NULL, NULL, 0, 0, '2025-09-11 17:23:11', 0, 1, NULL),
(30, NULL, 1, 3, 3, 'מגבר (4 רמקולים)', 'מגבר נייד, עוצמתי ומעוצב.\nמתחבר לכל מכשיר חשמלי עם יציאת אוזניות סטנדרטית (AUX).\nניתן לשלוטי על עוצמת הקול של כל זוג רמקולים בנפרד.\nמתאים לקייטנות, סדנאות, חוגים, בניה עצמית\nהקיט מופעל באמצעות סוללה 9V (כלולה).\nמבוסס רכיב PIC.\nמספר רכיבים: 35.\nזמן עבודה: 8 – 9 שיעורים (מחושב לפי 45 דקות לשיעור).\nדרגת קושי: בינוני – קשה.\nהרכבת מגבר', NULL, NULL, NULL, '97.80', '97.80', 100, 1, NULL, 'מגבר-4-רמקולים', NULL, NULL, NULL, NULL, 0, 0, '2025-09-11 17:23:11', 0, 1, NULL),
(31, NULL, 1, 3, 3, 'מגן דוד', 'מגן דוד אלקטרוני מאיר ומהבהב.\nתאורה כחולה.\nניתן לשנות את קצב ההבהוב.\nניתן להפסיק את ההבהוב על מנת לקבל תאורה מלאה.\nמתאים לקייטנות, סדנאות, חוגים, בניה עצמית\nהקיט מופעל באמצעות צמד סוללות 3V 2016 (כלולות).\nמבוסס רכיב 555.\nמספר רכיבים: 34.\nזמן עבודה: 6 שיעורים (מחושב לפי 45 דקות לשיעור).\nדרגת קושי: קל – בינוני.', NULL, NULL, NULL, '48.90', '48.90', 100, 1, NULL, 'מגן-דוד', NULL, NULL, NULL, NULL, 0, 0, '2025-09-11 17:23:11', 0, 1, NULL),
(32, NULL, 1, 3, 3, 'מדליה אלקטרונית', 'מדליה מאירה ומהבהבת.\nתאורה בשני צבעים שונים.\nניתן לשנות את קצב ההבהוב.\nניתן להפסיק את ההבהוב על מנת לקבל תאורה מלאה.\nמתאים לקייטנות, סדנאות, חוגים, בניה עצמית\nהקיט מופעל באמצעות צמד סוללות 3V 2016 (כלולות).\nמבוסס רכיב 555.\nמספר רכיבים: 56.\nזמן עבודה: 7 שיעורים (מחושב לפי 45 דקות לשיעור).\nדרגת קושי: קל – בינוני.\nהרכבת מדליה', NULL, NULL, NULL, '48.90', '48.90', 100, 1, NULL, 'מדליה-אלקטרונית', NULL, NULL, NULL, NULL, 0, 0, '2025-09-11 17:23:11', 0, 1, NULL),
(33, NULL, 1, 3, 3, 'מונה לחופש', 'מונה לחופש יספור לאחור את מספר הימים שנותרו עד לחופש המיוחל.\nביום המיוחל המוצר ינגן מנגינה.\nניתן לקדם ימים באופן ידני.\nמתאים לקייטנות, סדנאות, חוגים, בניה עצמית.\nהקיט מופעל באמצעות סוללה 9V (כלולה).\nמבוסס רכיב PIC.\nמספר רכיבים: 30.\nזמן עבודה: 6 שיעורים (מחושב לפי 45 דקות לשיעור).\nדרגת קושי: בינוני.', NULL, NULL, NULL, '76.10', '76.10', 100, 1, NULL, 'מונה-לחופש', NULL, NULL, NULL, NULL, 0, 0, '2025-09-11 17:23:11', 0, 1, NULL),
(34, NULL, 1, 3, 3, 'סירנה קטנה', 'מוצר מקסים שמתאים לאופניים\\קורקינט.\nהסירנה משמיעה 3 סוגי רעשים שונים (משטרה, אמבולנס, כיבוי אש).\nלסירנה לדים מהבהבים בצבעי משטרה (אדום, כחול).\nניתן להדליק\\לכבות את הבהוב הסירנה\nמתאים לקייטנות, סדנאות, חוגים, בניה עצמית.\nהקיט מופעל באמצעות צמד סוללות 1.5V (כלולות).\nמבוסס רכיב PIC.\nמספר רכיבים: 38.\nזמן עבודה: 7 שיעורים (מחושב לפי 45 דקות לשיעור).\nדרגת קושי: קל – בינוני.\nהצגת סירנה קטנה | הרכבת סירנה קטנה', NULL, NULL, NULL, '70.70', '70.70', 100, 1, NULL, 'סירנה-קטנה', NULL, NULL, NULL, NULL, 0, 0, '2025-09-11 17:23:11', 0, 1, NULL),
(35, NULL, 1, 3, 3, 'ספירת העומר', 'ספירת העומר יספור לאחור את מספר הימים שנותרו עד לחופש המיוחל.\nבכל יום יתנגן &quot;הנני מוכן ומזומן&quot;.\nניתן לקדם ימים באופן ידני.\nמתאים לקייטנות, סדנאות, חוגים, בניה עצמית.\nהקיט מופעל באמצעות סוללה 9V (כלולה).\nמבוסס רכיב PIC.\nמספר רכיבים: 30.\nזמן עבודה: 6 שיעורים (מחושב לפי 45 דקות לשיעור).\nדרגת קושי: בינוני.', NULL, NULL, NULL, '76.10', '76.10', 100, 1, NULL, 'ספירת-העומר', NULL, NULL, NULL, NULL, 0, 0, '2025-09-11 17:23:11', 0, 1, NULL),
(36, NULL, 1, 3, 3, 'עין ביונית', 'עין אלקטרונית שמצפצפת בכל פעם שעוברים לידה.\nלעין חיישן אור שמזהה שינויים בתאורה ומגיב בהתאם.\nניתן לשנות את רגישות החיישן.\nמתאים לקייטנות, סדנאות, חוגים, בניה עצמית.\nהקיט מופעל באמצעות סוללה 9V (כלולה).\nמבוסס רכיב 324.\nמספר רכיבים: 28.\nזמן עבודה: 6 שיעורים (מחושב לפי 45 דקות לשיעור).\nדרגת קושי: קל – בינוני.\nהצגת עין ביונית | הרכבת עין ביונית', NULL, NULL, NULL, '48.90', '48.90', 100, 1, NULL, 'עין-ביונית', NULL, NULL, NULL, NULL, 0, 0, '2025-09-11 17:23:11', 0, 1, NULL),
(37, NULL, 1, 3, 3, 'קוביטון', 'קוביה אקראית, מאירה ומנגנת.\nבכל פעם שמקבלים &quot;דאבל&quot; הקוביה מנגנת.\nהמוצר מתאים לכל משחקי הקוביה (שש – בש, מונופול וכו…).\nלקוביה לדים מהבהבים בצבעים שונים.\nמתאים לקייטנות, סדנאות, חוגים, בניה עצמית.\nהקיט מופעל באמצעות סוללה 9V (כלולה).\nמבוסס רכיב PIC.\nמספר רכיבים: 34.\nזמן עבודה: 6 שיעורים (מחושב לפי 45 דקות לשיעור).', NULL, NULL, NULL, '76.10', '76.10', 100, 1, NULL, 'קוביטון', NULL, NULL, NULL, NULL, 0, 0, '2025-09-11 17:23:11', 0, 1, NULL),
(38, NULL, 1, 3, 3, 'קופת חסכון\\צדקה', 'קופה אלקטרונית מעוצבת, מאירה, ומקליטה.\nניתן להקליט הודעה שתתנגן בכל פעם שנכניס כסף לקופה.\nקיים מצב חסכון בסוללה.\nמתאימה לכל סוגי המטבעות.\nמתאים לקייטנות, סדנאות, חוגים, בניה עצמית.\nהקיט מופעל באמצעות צמד סוללות 1.5V (כלולות).\nמבוסס רכיב PIC.\nמספר רכיבים: 43.\nזמן עבודה: 7 שיעורים (מחושב לפי 45 דקות לשיעור).\nדרגת קושי: בינוני.\nהצגת קופת חסכון\\צדקה | הרכבת קופת חסכון\\צדקה', NULL, NULL, NULL, '70.70', '70.70', 100, 1, NULL, 'קופת-חסכוןצדקה', NULL, NULL, NULL, NULL, 0, 0, '2025-09-11 17:23:11', 0, 1, NULL),
(39, NULL, 1, 3, 3, 'רכב אולטראסוני', 'רכב חומק ממכשולים.\nלרכב חיישן אולטראסוני ש&quot;חש&quot; מכשולים בנסיעה ומשנה כיוון.\nהרכב יסע ישר כל עוד אין מכשול מקדימה.\nלרכב תאורה צבעונית.\nמתאים לקייטנות, סדנאות, חוגים, בניה עצמית.\nהקיט מופעל באמצעות סוללה 9V (כלולה).\nמבוסס רכיב PIC.\nמספר רכיבים: 50.\nזמן עבודה: 8 – 10 שיעורים (מחושב לפי 45 דקות לשיעור).\nדרגת קושי: קשה.\nהרכבת רכב אולטראסוני | הרכבת קופסא', NULL, NULL, NULL, '130.50', '130.50', 100, 1, NULL, 'רכב-אולטראסוני', NULL, NULL, NULL, NULL, 0, 0, '2025-09-11 17:23:11', 0, 1, NULL),
(40, NULL, 1, 3, 3, 'רכב כפתורים', 'רובוט נוסע לפי תכנות.\nהרובוט &quot;זוכר&quot; את הכיוונים שעליו ליסוע בהתאם לתכנות שנעשה מראש.\nהתכנות נעשה באמצעות 4 לחצני כיוון.\nבנוסף קיים לחצן שמפיק צליל רובוטי חביב.\nלרובוט תאורה צבעונית.\nמתאים לקייטנות, סדנאות, חוגים, בניה עצמית.\nהקיט מופעל באמצעות סוללה 9V (כלולה).\nמבוסס רכיב PIC.\nמספר רכיבים: 85.\nזמן עבודה: 10 – 12 שיעורים (מחושב לפי 45 דקות לשיעור).\nדרגת קושי: קשה.\nהצגת רכב כפתורים', NULL, NULL, NULL, '130.50', '130.50', 100, 1, NULL, 'רכב-כפתורים', NULL, NULL, NULL, NULL, 0, 0, '2025-09-11 17:23:11', 0, 1, NULL),
(41, NULL, 1, 3, 3, 'רכב על שלט', 'רכב מתקדם וצבעוני עם שלט רחוק.\nשלט רחוק קומפקטי שנכנס לכיס.\nלרכב תאורה צבעונית.\nמתאים לקייטנות, סדנאות, חוגים, בניה עצמית.\nהקיט מופעל באמצעות סוללה 9V (כלולה).\nמבוסס רכיב PIC.\nמספר רכיבים: 82.\nזמן עבודה: 10 – 12 שיעורים (מחושב לפי 45 דקות לשיעור).\nדרגת קושי: קשה.\nהצגת רכב על שלט | הרכבת רכב על שלט | הרכבת קופסא', NULL, NULL, NULL, '130.50', '130.50', 100, 1, NULL, 'רכב-על-שלט', NULL, NULL, NULL, NULL, 0, 0, '2025-09-11 17:23:11', 0, 1, NULL),
(42, '1QO0G9S1W3K', 1, 2, 3, 'Scottie Go!', 'משחק חדשני ללימוד שפת תכנות לילדים ולצעירים. רמות קושי שונות וגיבורים ידידותיים במשחק מאפשרים לימוד תכנות מגיל צעיר, ללא צורך בניסיון קודם, כמו גם אספקת סביבות תכנות מאתגרות לשחקנים מנוסים יותר.\r\n!Scottie Go סדרת המשחקים כוללת חייזר ידידותי בשם סקוטי, שחווה הרפתקאות רבות בזמן שהוא מטייל בחלל עם החללית שלו.\r\nעל ידי עזרה לסקוטי, שחקנים צוברים ידע בתכנות ומפתחים מיומנויות וכישורים חשובים.', NULL, '', '', '54.40', '54.40', 100, 1, '', 'scottie-go', '', '', '', '', 0, 0, '2025-09-11 17:23:11', 0, 1, NULL),
(43, NULL, 1, 1, 3, 'מקרן פלטת צבעים', 'הילד אוהב מדע? מקרן פלטת הצבעים יאפשר לילדך ללמוד את פלטת הצבעים של האור בצגים ואת הצבעים שיווצרו משילובם. בנוסף הוא יוכל להיזכר בכל פעם שירצה.\nהמקרן מקרין את שלושת צבעי היסוד של האור: אדום ירוק וכחול (RGB)\nואת הצבעים המתקבלים משילובם: צהוב, מג\'נטה, ציאן ולבן (CMYK).\nמספר רכיבים: 16\nרמת קושי: בינוני – 5\nהרכבת מקרן 1 | הרכבת מקרן 2 | הרכבת מקרן 3', NULL, NULL, NULL, '32.60', '32.60', 100, 1, NULL, 'מקרן-פלטת-צבעים', NULL, NULL, NULL, NULL, 0, 0, '2025-09-11 17:23:11', 0, 1, NULL),
(44, NULL, 1, 4, 3, 'פנסופר (לד יחיד)', 'פנס עוצמתי וקומפקטי.\nהפנס משמש כמחזיק מפתחות.\nתאורת הפנס נעשית בעזרת לד לבן חזק.\nמצויין כפרוייקט ראשון.\nמתאים לקייטנות, סדנאות, חוגים, בניה עצמית.', NULL, NULL, NULL, '10.00', '10.00', 100, 1, NULL, 'פנסופר-לד-יחיד', NULL, NULL, NULL, NULL, 0, 0, '2025-09-11 17:23:11', 0, 1, NULL),
(45, NULL, 1, 4, 3, 'אתרוג מאיר (כולל חיישן)', 'הקישוט הייחודי לסוכה שכולם יעופו עליו והילד יוכל להראות את היכולות שלו ולא רק בציור.\nאתרוג מבוסס לדים שנדלק באופן אוטומטי כשמחשיך.\nהאתרוג מאיר בצבעים מתחלפים.\nניתן לתלות אותו כקישוט בסוכה.\nמספר רכיבים: 11\nרמת קושי: מתחילים – 3', NULL, NULL, NULL, '27.80', '27.80', 100, 1, NULL, 'אתרוג-מאיר-כולל-חיישן', NULL, NULL, NULL, NULL, 0, 0, '2025-09-11 17:23:11', 0, 1, NULL),
(46, NULL, 1, 4, 3, 'רכב אויר', NULL, NULL, NULL, NULL, '130.50', '130.50', 100, 1, NULL, 'רכב-אויר-1', NULL, NULL, NULL, NULL, 0, 0, '2025-09-11 17:23:11', 0, 1, NULL),
(47, NULL, 1, 4, 3, 'פנס טיולים', NULL, NULL, NULL, NULL, '20.00', '20.00', 100, 1, NULL, 'פנס-טיולים', NULL, NULL, NULL, NULL, 0, 0, '2025-09-11 17:23:11', 0, 1, NULL),
(48, NULL, 1, 4, 3, 'מג\'יקאר', NULL, NULL, NULL, NULL, '95.00', '95.00', 100, 1, NULL, 'מגיקאר', NULL, NULL, NULL, NULL, 0, 0, '2025-09-11 17:23:11', 0, 1, NULL),
(49, NULL, 1, 4, 3, 'בית העומר', 'יצירה אלקטרונית לימודית\nשתגרום לילדך לא לשכוח לספור את העומר.\nהלוח זוהר כשמכבים את האור.\nתאורה אלקטרונית שנדלקת בלחיצת כפתור.\nהערכה כוללת:\n\nכרטיס אלקטרוני\n8 רכיבי אלקטרוניקה\n25 כרטיסי ימים\nהוראות הדרכה ולימוד, של המעגל האלקטרוני\n\nיצירה מקורית ובלעדית, תוצרת הארץ.', NULL, NULL, NULL, '70.00', '70.00', 100, 1, NULL, 'בית-העומר', NULL, NULL, NULL, NULL, 0, 0, '2025-09-11 17:23:11', 0, 1, NULL),
