(59, NULL, 1, 3, 3, 'אזעקוד', 'ילדך רוצה פרטיות? קיט האזעקוד יאפשר לילדך לשמור על פרטיותו על ידי אזעקה שמופעלת בעזרת קוד. זהו מנגנון שהילד מרכיב והוא זה שיבחר את הסיסמא.\nניתן לבחור ולשנות את הקוד, כך שאם לא עושים את הרצף הנכון האזעקוד ישמיע אזעקה.\nהאזעקה מתריעה בעוצמה במקרים בהם הדלת או החלון נפתחים ללא אישור.\nכאשר הדלת נסגרת, ההתרעה אינה נעצרת, אלא ממשיכה עד להזנת הקוד הנכון.\nמספר רכיבים:\nרמת קושי: מקצוענים – 6', NULL, NULL, NULL, '72.00', '72.00', 100, 1, NULL, 'אזעקוד-1', NULL, NULL, NULL, NULL, 0, 0, '2025-09-11 17:23:11', 0, 1, NULL),
