(63, NULL, 1, 4, 3, 'מזכירון', 'מכשיר להקלטת תזכורת.\nמתאים לקייטנות, סדנאות, חוגים, בניה עצמית.\nהקיט מופעל באמצעות צמד סוללות 3V 2016 (כלולות)\nמספר רכיבים: 25.\nזמן עבודה: 5 שיעורים (מחושב לפי 45 דקות לשיעור).\nדרגת קושי: בינוני.', NULL, NULL, NULL, '60.00', '60.00', 100, 1, NULL, 'מזכירון-1', NULL, NULL, NULL, NULL, 0, 0, '2025-09-11 17:23:11', 0, 1, NULL),
