(73, NULL, 1, 7, 3, 'טרמוקאפ', 'הכוס הכי מגניבה ויחודית – כזו שהילד ירצה לשתות רק איתה, ולך יהיה נוח לנקות.\nכוס בטיחות המודדת את טמפרטורת מים.\nבמידה והמים חמים הכוס תתריע בכך שאור ידלק.\nהכוס מיוצרת מפלסטיק מאושר למזון והיא בטוחה לשתייה.\nניתן להסיר את החלקים האלקטרונים בקלות ולשטוף את הכוס בין שימוש לשימוש.\nמספר רכיבים: 8\nרמת קושי: מתחילים – 2\nהסבר מדליכוס | הרכבת מדליכוס', NULL, NULL, NULL, '85.00', '85.00', 100, 1, NULL, 'טרמוקאפ', NULL, NULL, NULL, NULL, 0, 0, '2025-09-11 17:23:11', 0, 1, NULL),
